steps_json:
[
    {
        "title": "识别函数形态",
        "description": "将函数配方：$f(x)=x^2-2x+1=(x-1)^2$，它是一条开口向上的抛物线。",
        "bubbleText": "先把它变成平方的样子，$(x-1)^2$ 会直接告诉我们最低点在哪里。",
        "bubblePos": {
            "x": 210,
            "y": 160
        }
    },
    {
        "title": "找出顶点坐标",
        "description": "由顶点式 $f(x)=(x-1)^2$ 可知顶点为 $(1,0)$，因此对称轴是经过顶点的直线 $x=1$。",
        "bubbleText": "平方项等于零时，$x=1$，这就是抛物线的最低点，对称轴也经过这里。",
        "bubblePos": {
            "x": 270,
            "y": 220
        }
    },
    {
        "title": "理解单调区间",
        "description": "开口向上的抛物线在对称轴右侧单调递增，在对称轴左侧单调递减。题给区间 $[1,3]$ 正好位于右侧。",
        "bubbleText": "从最低点往右走，图象一路向上，所以区间 $[1,3]$ 的确是递增的。",
        "bubblePos": {
            "x": 390,
            "y": 350
        }
    },
    {
        "title": "用导数确认",
        "description": "$f'(x)=2x-2$。当 $x\\in[1,3]$ 时，$f'(x)\\geq0$，所以函数在该区间上单调递增。",
        "bubbleText": "导数像是在看上坡还是下坡；这里始终不小于零，说明一直在上升。",
        "bubblePos": {
            "x": 235,
            "y": 265
        }
    },
    {
        "title": "对应选项",
        "description": "对称轴为 $x=1$，与选项 A 一致，因此选择 A。",
        "bubbleText": "把算出的对称轴和选项逐个对照，$x=1$ 对应 A。",
        "bubblePos": {
            "x": 555,
            "y": 420
        }
    },
    {
        "title": "验证结论",
        "description": "关于 $x=1$ 对称时，任意 $t$ 都满足 $f(1-t)=f(1+t)=t^2$，故对称轴确为 $x=1$，答案正确。",
        "bubbleText": "左右离开 $x=1$ 同样远，函数值就相同，这说明这条轴真的把图象分成对称的两边。",
        "bubblePos": {
            "x": 570,
            "y": 270
        }
    }
]
